// Tests can cause Python to cache bytecode in the writable unpacked distribution.
// Remove only generated bytecode below this project's packaged runtime, never data.
const fs=require('node:fs'),path=require('node:path'),pkg=require('../package.json');
const project=path.resolve(__dirname,'..'),out=path.resolve(project,pkg.build.directories.output,'win-unpacked');
const runtime=path.resolve(out,'resources/runtime');
if(!runtime.startsWith(out+path.sep)||!fs.existsSync(path.join(out,'MediaSail.exe')))throw new Error('Unexpected packaged directory');
let count=0;
function walk(dir){for(const entry of fs.readdirSync(dir,{withFileTypes:true})){
 const file=path.resolve(dir,entry.name);if(!file.startsWith(runtime+path.sep))throw new Error('Cleanup escaped packaged runtime');
 if(entry.isSymbolicLink())continue;
 if(entry.isDirectory()){if(entry.name==='__pycache__'){fs.rmSync(file,{recursive:true,force:true});count++;}else walk(file);}
 else if(entry.name.endsWith('.pyc')){fs.unlinkSync(file);count++;}
}}
walk(runtime);console.log(`Removed ${count} generated bytecode entries from packaged runtime only`);
